     7	function BaseAttachmentViewPdf({
     8	    file,
     9	    encryptedSourceUrl,
    10	    isFocused,
    11	    onPress: onPressProp,
    12	    onScaleChanged: onScaleChangedProp,
    13	    onToggleKeyboard,
    14	    onLoadComplete,
    15	    style,
