    17	    onLoadError,
    18	}: AttachmentViewPdfProps) {
    19	    const attachmentCarouselPagerContext = useContext(AttachmentCarouselPagerContext);
    20	    const isScrollEnabled = attachmentCarouselPagerContext === null ? undefined : attachmentCarouselPagerContext.isScrollEnabled;
    21	
    22	    useEffect(() => {
    23	        if (!attachmentCarouselPagerContext) {
    24	            return;
    25	        }
    26	        attachmentCarouselPagerContext.onScaleChanged(1);
    27	        // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps -- we just want to call this function when component is mounted
    28	    }, []);
    29	
    30	    /**
    31	     * When the PDF's onScaleChanged event is triggered, we must call the context's onScaleChanged callback,
    32	     * because we want to disable the pager scroll when the pdf is zoomed in,
    33	     * as well as call the onScaleChanged prop of the AttachmentViewPdf component if defined.
    34	     */
    35	    const onScaleChanged = useCallback(
    36	        (newScale: number) => {
    37	            if (onScaleChangedProp !== undefined) {
    38	                onScaleChangedProp(newScale);
    39	            }
    40	
    41	            // When a pdf is shown in a carousel, we want to disable the pager scroll when the pdf is zoomed in
    42	            if (attachmentCarouselPagerContext?.pagerRef) {
    43	                attachmentCarouselPagerContext.onScaleChanged(newScale);
    44	            }
    45	        },
    46	        [attachmentCarouselPagerContext, onScaleChangedProp],
    47	    );
    48	
    49	    /**
    50	     * This callback is used to pass-through the onPress event from the AttachmentViewPdf's props
    51	     * as well trigger the onTap event from the context.
    52	     * The onTap event should only be triggered, if the pager is currently scrollable.
    53	     * Otherwise it means that the PDF is currently zoomed in, therefore the onTap callback should be ignored
